import itertools

def include_patient_records(patient_records, selectors):
    """
    Takes in two lists: patient_records and selectors.
    Returns a new list consisting of patient records where the corresponding selector is True.
    If the selector list is exhausted, remaining patient records should also be included in the output list.
    """
    result = []
    for i, record in enumerate(patient_records):
        if i < len(selectors):
            if selectors[i]:
                result.append(record)
        else:
            # If selectors list is exhausted, include remaining patient records
            result.append(record)
    return result

